def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_pressure = 0.0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('budget', 0) > 200:
                rich_pressure += 1.0

    if not alive_opponents:
        return max(0.0, min(float(budget), 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_factor = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_factor < 0:
        supply_factor = 0.0
    if supply_factor > 1:
        supply_factor = 1.0

    bid = 0.0

    if hp <= 2 or no_water >= 2:
        bid = max(88.0, highest_prev + 2.0)
    elif hp <= 4 or no_water >= 1:
        bid = max(62.0, avg_prev * 0.8 + 4.0)
    else:
        if supply >= 22:
            bid = 18.0 + rich_pressure * 2.0
        elif supply >= 19:
            bid = 28.0 + rich_pressure * 3.0
        else:
            bid = 42.0 + rich_pressure * 4.0

        if highest_prev >= 100.0:
            bid = min(bid, 30.0)
        elif highest_prev >= 85.0:
            bid = max(bid, 36.0)
        elif highest_prev > 0:
            bid = max(bid, min(60.0, highest_prev * 0.72 + 3.0))

    if day >= 8:
        bid += 8.0
    if day >= 9 and hp <= 5:
        bid += 12.0

    if budget <= 0:
        return 0.0

    min_safe = 0.0
    if hp <= 4 or no_water >= 1:
        min_safe = 20.0

    bid = max(min_safe, bid)
    bid = min(float(budget), bid)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], WATER_REQ * 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_bid = DAILY_SALARY * 0.65

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)

        if max_yesterday_bid > DAILY_SALARY * 0.8:
            if my_status['hp'] <= 3:
                current_bid = max(current_bid, max_yesterday_bid + (DAILY_SALARY * 0.2))
            elif my_status['hp'] <= 5:
                current_bid = max(current_bid, max_yesterday_bid + (DAILY_SALARY * 0.1))
            else:
                current_bid = max(current_bid, avg_yesterday_bid + (DAILY_SALARY * 0.05))
        elif max_yesterday_bid < DAILY_SALARY * 0.4:
            current_bid = min(current_bid, max_yesterday_bid + (DAILY_SALARY * 0.1))
        else:
            current_bid = max(current_bid, avg_yesterday_bid + (DAILY_SALARY * 0.05))

    if my_status['hp'] <= 2:
        current_bid = max(current_bid, DAILY_SALARY * 1.1)
    elif my_status['hp'] <= 4:
        current_bid = max(current_bid, DAILY_SALARY * 0.9)
    elif my_status['hp'] >= 8:
        current_bid = min(current_bid, DAILY_SALARY * 0.7)

    if day_context['day'] >= EPISODE_DAYS * 0.7 and my_status['hp'] > 5:
        current_bid = max(current_bid, DAILY_SALARY * 0.9)

    num_active_players = len(alive_opponents) + 1
    estimated_total_water_needed = num_active_players * WATER_REQ

    if day_context['supply'] < estimated_total_water_needed:
        current_bid = current_bid * 1.1
    elif day_context['supply'] > estimated_total_water_needed * 1.5:
        current_bid = current_bid * 0.9

    final_bid = max(1.0, min(my_status['budget'], current_bid))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids to infer aggressiveness
    prev_bids = []
    prev_pressures = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        # If they ran out of water days recently, they may be under pressure
        hp_after = prev.get('hp_after', None)
        status = prev.get('status', None)
        if status is not None or hp_after is not None:
            # crude pressure score
            try:
                if hp_after is not None and float(hp_after) <= 0:
                    prev_pressures.append(2.0)
                else:
                    prev_pressures.append(1.0)
            except Exception:
                prev_pressures.append(1.0)

    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: lower supply means higher chance we must win water
    # Normalize supply to [0,1] where 1 is scarce.
    scarce = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    scarce = max(0.0, min(1.0, scarce))

    # Decide target bid level.
    # If supply is scarce or we are already several days without water, bid higher.
    # If opponents previously bid extremely high (max_prev_bid), avoid matching fully unless necessary.
    need_factor = 0.0
    if no_water_days >= 2:
        need_factor += 0.8
    elif no_water_days == 1:
        need_factor += 0.4

    if hp <= 2:
        need_factor += 1.2
    elif hp <= 4:
        need_factor += 0.6
    elif hp <= 7:
        need_factor += 0.3

    # Base willingness
    base = DAILY_SALARY * (0.35 + 0.35 * scarce)  # ~0.35-0.70 of salary
    # Add reaction to opponents' aggressiveness
    # If max_prev_bid was huge, they likely overbid; we can undercut slightly.
    # If avg_prev_bid is high, competition is real.
    if max_prev_bid >= DAILY_SALARY * 0.7:
        # Don't chase; bid just enough.
        comp = DAILY_SALARY * 0.55
    elif avg_prev_bid >= DAILY_SALARY * 0.45:
        comp = DAILY_SALARY * 0.62
    else:
        comp = DAILY_SALARY * 0.48

    target = max(base, comp) + DAILY_SALARY * (0.25 * need_factor)

    # Cap by budget and avoid suicidal bids
    # Also, if budget is low, bid proportionally.
    if budget <= 0:
        return 0.0

    # Conservative cap: never spend more than 60% of current budget in a single day
    max_spend = budget * 0.6
    bid = min(target, max_spend)

    # If we are in critical HP state, allow up to 90% of budget
    if hp <= 2.5:
        bid = min(target, budget * 0.9)

    # Ensure bid is non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)
